-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 9: Integridade — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('fb803f47-4443-5ea6-b0af-75b26e61429c', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Uma restrição com parâmetros ainda não substituídos por valores é um:', '["Predicado.","Plano de disco.","Cursor.","Commit.","Backup."]'::jsonb, 0, 'Ao instanciar parâmetros, o predicado dá origem a uma proposição avaliável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.3, páginas 441–442 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('28df7380-ff27-5eaa-bde6-e91e927f7730', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'O predicado de uma relvar combina suas restrições por:', '["Ordenação física.","Conjunção lógica.","Concatenação de nomes.","Soma de cardinalidades.","Disjunção exclusiva."]'::jsonb, 1, 'Todas as restrições aplicáveis devem ser simultaneamente satisfeitas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.4, páginas 443–444 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d3c5689-c7f5-524f-aac8-eff3d8616da6', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'A Regra Áurea da integridade impede uma atualização que:', '["Modifique uma tabela vazia.","Use uma expressão aninhada.","Altere qualquer valor persistente.","Faça o predicado do banco resultar falso.","Consulte mais de uma relvar."]'::jsonb, 3, 'Atualizações são admissíveis apenas se preservarem as restrições do banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.4, páginas 443–444 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eff531fc-fa7a-5708-a4bc-b18bee6779d6', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Uma restrição interna é suficiente para garantir correspondência perfeita com o mundo real?', '["Sim, desde que exista uma chave primária.","Não; o sistema verifica o que foi formalizado, não toda a realidade externa.","Não, porque restrições nunca são verificáveis.","Sim, pois consistência e verdade externa são idênticas.","Sim, se houver apenas uma tabela."]'::jsonb, 1, 'As regras declaradas podem não capturar erros ou mudanças da realidade externa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.6, páginas 447–449 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('883e8123-e156-52c5-8704-1a0d69174296', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Um banco satisfaz todas as regras declaradas, mas contém o telefone antigo de uma pessoa. Ele pode estar:', '["Correto externamente, pois possui formato válido.","Necessariamente normalizado até 5FN.","Inconsistente por definição, ainda que nenhuma regra seja violada.","Sem qualquer predicado.","Consistente internamente e incorreto em relação à realidade."]'::jsonb, 4, 'Consistência com restrições não garante que cada fato corresponda à situação real.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.7, páginas 450–451 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4a873623-3cb4-5469-b2c6-850d6a802f4e', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'A condição saldo maior ou igual a zero em uma relvar é exemplo de:', '["Descrição de rede.","Permissão de acesso por usuário.","Operação de backup.","Restrição sobre os dados admissíveis.","Plano físico de busca."]'::jsonb, 3, 'Integridade trata da validade dos estados, diferentemente de autorização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.9, páginas 454–457 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('be3ecf5b-e537-51a3-841d-a06cd25ffc15', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Uma chave candidata é uma superchave que também possui:', '["Uma referência externa obrigatória.","Exatamente um atributo.","Irredutibilidade.","Ordenação física.","Tipo numérico obrigatório."]'::jsonb, 2, 'Nenhum subconjunto próprio da chave candidata mantém a identificação única.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('75122044-b18b-50d1-9906-b848928e67d8', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Se {A} já identifica unicamente as tuplas, {A,B} é necessariamente uma chave candidata?', '["Sim, pois mais atributos aumentam a minimalidade.","Não, porque superchaves são proibidas.","Sim, desde que B seja texto.","Sim, todo conjunto único é candidato.","Não; ela é uma superchave não mínima."]'::jsonb, 4, 'Acrescentar B preserva unicidade, mas destrói a irredutibilidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cf27f673-bd22-5bd3-a31a-3b8303f66dca', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Fácil', 'Uma relvar pode possuir duas chaves candidatas diferentes?', '["Não, porque todos os atributos precisam ser numéricos.","Não; só existe uma combinação única possível.","Sim; uma delas pode ser designada primária.","Sim, somente se tiver uma tupla.","Sim, mas ambas deixam de ser candidatas."]'::jsonb, 2, 'A escolha de chave primária não elimina outras chaves candidatas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2c1414ca-5a8e-511e-b5be-0e3df4c841c7', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Qual característica de uma chave candidata é independente da escolha da chave primária?', '["Possuir o menor número de bytes entre todas as chaves.","Ser sempre a primeira coluna.","Estar fisicamente ordenada.","Ser criada automaticamente por uma junção.","Identificar unicamente as tuplas com um conjunto irredutível de atributos."]'::jsonb, 4, 'Irredutibilidade não significa escolher a chave de menor tamanho físico.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c7a63035-961b-5ce4-abb4-687052e76a86', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Fácil', 'Uma chave estrangeira expressa principalmente:', '["Uma exigência de correspondência com uma chave referenciada.","Uma garantia de confidencialidade.","Uma permissão de exclusão.","Uma obrigação de ordenar o arquivo.","Uma cópia integral de outra relação."]'::jsonb, 0, 'A integridade referencial impede referências incompatíveis com o estado da relação referenciada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('25309e77-a2fe-557b-862f-5ac6c79db82a', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Um item referencia um pedido inexistente. Qual categoria de integridade é diretamente afetada?', '["Somente a ordenação de saída.","Referencial.","Somente a duração da transação.","Somente a codificação física.","Somente a segurança de leitura."]'::jsonb, 1, 'A referência precisa corresponder ao objeto admitido pela restrição declarada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf27c216-bc16-5a3c-a84d-e85a5be83c93', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma exclusão com regra RESTRICT deve fazer o quê quando existirem dependentes impeditivos?', '["Substituir todas as chaves por zero.","Excluir silenciosamente os dependentes.","Rejeitar a exclusão.","Desativar a chave estrangeira.","Confirmar antes de verificar referências."]'::jsonb, 2, 'RESTRICT bloqueia a operação que violaria a referência, em vez de propagá-la.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1ea07c02-35ba-5dd5-9724-c63841d4b3e9', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma regra ON DELETE CASCADE determina:', '["Propagação da exclusão aos registros dependentes alcançados pela regra.","Rejeição de toda exclusão, mesmo sem dependentes.","Cópia do registro para outra tabela.","Propagação de permissões a todos os usuários.","Conversão de todas as referências em índices."]'::jsonb, 0, 'A ação em cascata integra a política de manutenção da integridade referencial.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('91114071-69b9-5be8-9c25-93da83c7dadd', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Um trigger associa uma ação a:', '["Uma função de rede obrigatória.","Um nome de usuário sem evento.","Um evento especificado no banco.","Toda impressão de tela.","Uma única posição fixa de disco."]'::jsonb, 2, 'Gatilhos executam ações em resposta aos eventos para os quais foram definidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.11, páginas 470–473 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e2fcbb6-5bd0-56ff-aa5d-8cfa40eaaa6b', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Por que um trigger não deve ser confundido com uma restrição declarativa?', '["Ele especifica uma ação disparada por evento, não apenas uma condição de validade.","Porque não depende de eventos.","Porque não possui condições de execução.","Porque nunca pode alterar dados.","Porque substitui todas as chaves."]'::jsonb, 0, 'Ações procedimentais e declarações de estados admissíveis têm contratos diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.11, páginas 470–473 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b32e66c0-ce4e-5697-85ad-4289f3273c20', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Na abordagem defendida por Date, cabe ao usuário programar a ordem de todas as verificações de restrições?', '["Sim, usando sempre cursores.","Não; o SGBD deve determinar as verificações necessárias.","Sim, para cada consulta de leitura.","Não, porque nenhuma verificação é necessária.","Sim, por meio da ordem física das linhas."]'::jsonb, 1, 'O autor defende tratamento declarativo e verificação pelo sistema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.5, páginas 445–446 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8ee7f61c-6901-5435-9c41-00f278422283', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Uma atualização feita por uma visão pode ignorar as restrições das relvars envolvidas?', '["Sim, se o usuário não conhecer as tabelas.","Sim, porque visões não possuem ligação com dados básicos.","Não, porque visões nunca podem ser consultadas.","Não; os efeitos precisam preservar a integridade do banco.","Sim, pois fechamento dispensa restrições."]'::jsonb, 3, 'A interface usada para atualizar não elimina os requisitos de integridade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.8, páginas 452–453 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4fcb00a4-7d65-5dc5-9c82-4a46bd4f644b', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Qual construção SQL representa diretamente uma condição de validade dos dados?', '["COMMIT.","ORDER BY.","GRANT.","EXPLAIN.","CHECK."]'::jsonb, 4, 'CHECK declara um predicado que os dados devem satisfazer segundo as regras SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.12, páginas 474–480 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('04359e3d-5f07-522c-9254-18719b7b053d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Adicionar uma restrição UNIQUE em outra combinação de colunas serve principalmente para:', '["Autorizar qualquer usuário a alterar linhas.","Transformar a tabela em visão.","Tornar a tabela obrigatoriamente ordenada.","Impedir repetição dessa combinação segundo a semântica SQL.","Criar uma referência externa obrigatória."]'::jsonb, 3, 'Unicidade é uma condição de integridade, não uma garantia de apresentação ou acesso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
